import React, { useEffect, useCallback } from "react";
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
} from "@mui/material";
import { showSuccessToast } from "common/ToastMessage";
import CommonMessage from "common/CommonMessage";
import { useDispatch, useSelector } from "react-redux";
import FormInputSelect from "components/form/FormInputSelect";
import { useForm } from "react-hook-form";
import { getUsers } from "modules/administration/slices/usersSlice";
import { lockApplication } from "modules/credit-management/slices/applicationSlice";

const AssignUserModal = ({ open, onClose, selectedRow, fetchApi }) => {
  const dispatch = useDispatch();

  const { control, handleSubmit, reset } = useForm({});

  const { users } = useSelector((state) => state.users);

  useEffect(() => {
    if (open) {
      dispatch(getUsers("IHCO"));
      reset();
    }
  }, [open,reset]);

  const onSubmit = useCallback(
    () => async (body) => {

      onClose();
      const ihco = users?.find((item)=> item.id ===  body.locked_user_uuid);
      try {
        await dispatch(
          lockApplication({
            data: {
              application_id: selectedRow.id,
              locked_user_uuid: ihco.uuid,
              is_locked: 1,
            },
          })
        ).unwrap();
        showSuccessToast(CommonMessage.MFS00014);
        fetchApi()
      } catch (error) {
        console.error("Error", error);
      }
    },
    [selectedRow,users]
  );

  return (
    <Dialog open={open}>
      <DialogTitle textAlign="center">Assign User</DialogTitle>
      <DialogContent>
        <Stack
          sx={{
            width: "100%",
            minWidth: { xs: "300px", sm: "360px", md: "400px" },
            gap: "1.5rem",
            mt: 1,
            marginTop: "30px",
          }}
        >
          <FormInputSelect
            control={control}
            options={users ?? []}
            getOptionLabel={(option) => option?.user_name || ""}
            id="id"
            name="locked_user_uuid"
            label={<span className="required">IHCO</span>}
            rules={{
              required: true,
            }}
          />
        
        </Stack>
        <DialogActions sx={{ p: "1.25rem" }}>
          <Button
            onClick={() => {
              onClose();
            }}
          >
            Cancel
          </Button>
          <Button
            type="submit"
            onClick={handleSubmit(onSubmit())}
            variant="contained"
          >
            OK
          </Button>
        </DialogActions>
      </DialogContent>
    </Dialog>
  );
};

export default AssignUserModal;
